/* Decode one value at `at`; returns the next offset. */
static inline size_t kaya_parse_value(const uint8_t *buf, size_t at, KayaVal *out) {
    memcpy(&out->type, buf + at, 4);
    uint32_t len;
    memcpy(&len, buf + at + 4, 4);
    out->i = 0;
    out->f = 0;
    out->s = 0;
    out->s_len = 0;
    switch (out->type) {
    case KAYA_VALUE_BOOL:
        out->i = buf[at + 8];
        break;
    case KAYA_VALUE_I64:
    case KAYA_VALUE_BLOB:
        memcpy(&out->i, buf + at + 8, 8);
        break;
    case KAYA_VALUE_F64:
        memcpy(&out->f, buf + at + 8, 8);
        break;
    default:
        out->s = (const char *)(buf + at + 8);
        out->s_len = len;
    }
    return at + 8 + ((len + 7) & ~7u);
}

/* Decode one occurrence record (header included). Returns 1 for a
 * click, filling id and up to max_keys of the copy's key path
 * (empty for a click on a guest-created widget); 0 otherwise. */
static inline int kaya_parse_click(const uint8_t *rec, uint64_t *id,
                                   KayaVal *keys, uint32_t max_keys,
                                   uint32_t *n_keys) {
    const KayaRecordButtonClicked *r = (const KayaRecordButtonClicked *)rec;
    if (r->header.kind != KAYA_OCCURRENCE_BUTTON_CLICKED)
        return 0;
    *id = r->id;
    *n_keys = r->path_len;
    size_t at = sizeof(KayaRecordButtonClicked);
    for (uint32_t k = 0; k < r->path_len && k < max_keys; k++)
        at = kaya_parse_value(rec, at, &keys[k]);
    return 1;
}

/* Decode a menu_activated occurrence: the click identity shape — id plus
 * path_len key-path values (a node-anchored context activation
 * carries the stamped copy's keys; path_len is 0 for a bar or
 * live-widget item). Returns 1 and fills the outputs, or 0 for
 * other kinds. */
static inline int kaya_parse_menu_activated(const uint8_t *rec, uint64_t *id,
                                             KayaVal *keys, uint32_t max_keys,
                                             uint32_t *n_keys) {
    const KayaRecordButtonClicked *r = (const KayaRecordButtonClicked *)rec;
    if (r->header.kind != KAYA_OCCURRENCE_MENU_ACTIVATED)
        return 0;
    *id = r->id;
    *n_keys = r->path_len;
    size_t at = sizeof(KayaRecordButtonClicked);
    for (uint32_t k = 0; k < r->path_len && k < max_keys; k++)
        at = kaya_parse_value(rec, at, &keys[k]);
    return 1;
}

/* Decode a sort_requested occurrence: id plus path_len key-path values,
 * plus `column` from the slot the click family pads. Returns 1 and
 * fills the outputs, or 0 for other kinds. */
static inline int kaya_parse_sort_requested(const uint8_t *rec, uint64_t *id,
                                             KayaVal *keys, uint32_t max_keys,
                                             uint32_t *n_keys, uint32_t *column) {
    const KayaRecordButtonClicked *r = (const KayaRecordButtonClicked *)rec;
    if (r->header.kind != KAYA_OCCURRENCE_SORT_REQUESTED)
        return 0;
    *id = r->id;
    *n_keys = r->path_len;
    memcpy(column, rec + 20, sizeof(uint32_t)); /* the click family's pad slot */
    size_t at = sizeof(KayaRecordButtonClicked);
    for (uint32_t k = 0; k < r->path_len && k < max_keys; k++)
        at = kaya_parse_value(rec, at, &keys[k]);
    return 1;
}

